"""Verify exact Git source and qualify the old snapshots' exercised paths."""
import ast,copy,hashlib,json,subprocess
from pathlib import Path
r=Path(__file__).absolute().parent;repo=r.parent.parent
revisions={'baseline':'870c8de056d600a54729ceba434b55178e07549c','candidate':'49c4c7311fdb791258d6ab044843ebccca3c500b','reviewed':'f232cd72c6795d12ac4ddbf90444930b3c1f8d80','final':'49079dd673d38f26eb9a15193a1546c57e0bdffa'}
snapshots={}
for name,rev in revisions.items():
 files=subprocess.check_output(['git','ls-tree','-r','--name-only',rev,'--','src/embodiedforge'],text=True).splitlines();hashes={}
 for relative in files:
  expected=subprocess.check_output(['git','show',f'{rev}:{relative}']);actual=(r/name/relative).read_bytes();assert actual==expected,(name,relative);hashes[relative.removeprefix('src/embodiedforge/')]=hashlib.sha256(actual).hexdigest()
 snapshots[name]=dict(revision=rev,matched_files=len(files),hashes=hashes)
current={str(p.relative_to(repo/'src/embodiedforge')):hashlib.sha256(p.read_bytes()).hexdigest() for p in (repo/'src/embodiedforge').rglob('*') if p.is_file() and '__pycache__' not in str(p) and p.suffix!='.pyc'}
assert current==snapshots['final']['hashes']
experimental={str(p.relative_to(r/'experimental-collate/src/embodiedforge')):hashlib.sha256(p.read_bytes()).hexdigest() for p in (r/'experimental-collate/src/embodiedforge').rglob('*') if p.is_file() and '__pycache__' not in str(p) and p.suffix!='.pyc'}
assert experimental==current
changes={name:[path for path,sha in data['hashes'].items() if current[path]!=sha] for name,data in snapshots.items()}
assert set(changes['candidate'])=={'go1_live.py','batching.py'}
assert changes['reviewed']==['batching.py']
def without_collate(path):
 tree=ast.parse(path.read_text())
 for node in tree.body:
  if isinstance(node,ast.FunctionDef) and node.name=='_collate':node.body=[ast.Pass()]
 return ast.dump(tree,include_attributes=False)
assert without_collate(r/'candidate/src/embodiedforge/batching.py')==without_collate(repo/'src/embodiedforge/batching.py')
proof=dict(status='passed',snapshots=snapshots,changes_to_final=changes,experimental_collate_all_files_equal_final=True,all_batching_ast_equal_except_collate_body=True,qualifications={'identity_endurance':'candidate 49c4c73: go1_live outside exercised path; batching differs only _collate body and harness uses shuffle_buffer=0, so _ordered_batches and all dependencies are AST-identical. Full 153-file candidate source is preserved, not described as final exact-byte source.','rollout_endurance':'reviewed f232cd7: only batching.py differs; this module is outside rollout/record/read exercised path. All other 152 packaged files match final exactly.','live_endurance':'reviewed f232cd7: both go1_live.py and _live_channel.py match final exactly; only batching.py differs outside this component path.','batch_endurance':'before reviewed f232cd7 vs after final 49079dd: all package sources verified against their declared Git revisions; exact final source snapshot is exercised.','native_live_check':'reviewed f232cd7 matches final in all files except batching.py, outside live worker path.','channel_measurements':'candidate 49c4c73 _live_channel.py exactly equals final source; baseline is 870c8de.','collate_pipeline_measurements':'before reviewed f232cd7; experimental and final all 153 packaged files exactly equal final 49079dd.'})
old_benchmark=subprocess.check_output(['git','show','49c4c7311fdb791258d6ab044843ebccca3c500b:benchmarks/live_channel.py'],text=True)
new_benchmark=(repo/'benchmarks/live_channel.py').read_text()
def measured_function(text):return ast.dump(next(node for node in ast.parse(text).body if isinstance(node,ast.FunctionDef) and node.name=='measure'),include_attributes=False)
assert measured_function(old_benchmark)==measured_function(new_benchmark)
assert subprocess.check_output(['git','show','870c8de:benchmarks/dataset_reads.py'])==(repo/'benchmarks/dataset_reads.py').read_bytes()
proof['benchmark_qualifications']=dict(live_channel_measure_function_ast_identical_to_first_measured_revision='49c4c7311fdb791258d6ab044843ebccca3c500b',dataset_reads_benchmark_bytes_identical_to_round_baseline=True,scope='Later live-channel CLI input support changes fixture selection/report metadata; the timed receive function is AST-identical. The existing dataset reader benchmark is byte-identical.')
(r/'source-proof.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps(dict(status='passed',matched={k:v['matched_files'] for k,v in snapshots.items()},changes_to_final=changes)))

