import hashlib,json,os,statistics,subprocess,sys,time
from pathlib import Path
r=Path(__file__).absolute().parent;repo=r.parent.parent
baseline=r/'baseline/src';candidate=repo/'src';start=time.time();rows=[]
configs=[(0,10000),(128,10000),(4096,2000),(65520,300),(65536,300),(262144,150),(1048576,64),(4000000,32)]
source={name:hashlib.sha256((path/'embodiedforge/_live_channel.py').read_bytes()).hexdigest() for name,path in [('before',baseline),('after',candidate)]}
for pair in range(20):
 for size,count in configs:
  for name in (['before','after'] if pair%2==0 else ['after','before']):
   dest=r/f'channel-pair-{pair:02d}-{size}-{name}.json'
   command=[sys.executable,str(repo/'benchmarks/live_channel.py'),'--payload-bytes',str(size),'--messages',str(count),'--repeats','3','--output',str(dest)]
   env=dict(os.environ,PYTHONPATH=str(baseline if name=='before' else candidate),OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1')
   p=subprocess.run(command,env=env,capture_output=True,text=True)
   if p.returncode:raise RuntimeError(p.stderr)
   row=json.loads(dest.read_text());rows.append(dict(pair=pair,version=name,**row))
  print(json.dumps(dict(pair=pair,payload_bytes=size,rows=len(rows))),flush=True)
  (r/'channel-pairs-progress.json').write_text(json.dumps(dict(started_epoch=start,updated_epoch=time.time(),rows=len(rows),pair=pair,payload_bytes=size)))
summary=[]
for size,_ in configs:
 group=[x for x in rows if x['payload_bytes']==size]
 assert len({x['input_sha256'] for x in group})==1
 med={name:statistics.median(x['median_seconds_per_message'] for x in group if x['version']==name) for name in source}
 peaks={name:statistics.median(x['allocation']['peak_traced_bytes'] for x in group if x['version']==name) for name in source}
 summary.append(dict(payload_bytes=size,median_seconds=med,speedup=med['before']/med['after'],median_peak_bytes=peaks))
assert source=={name:hashlib.sha256((path/'embodiedforge/_live_channel.py').read_bytes()).hexdigest() for name,path in [('before',baseline),('after',candidate)]}
(r/'channel-pairs.json').write_text(json.dumps(dict(status='passed',started_epoch=start,ended_epoch=time.time(),source_hashes=source,scope='20 alternating independent process pairs/config; separate traced allocation; real socket receive + JSON decode + equality; shared host, no training-throughput claim',summary=summary,rows=rows),indent=2)+'\n')
print(json.dumps(summary,indent=2),flush=True)

