"""Try simplifying only schema validation; keep stack and ownership unchanged."""
import hashlib,importlib.util,json,os,shutil,statistics,sys,time,tracemalloc
from pathlib import Path
import numpy as np
r=Path(__file__).absolute().parent
from embodiedforge.batching import _collate as before
p=r/'reviewed/src/embodiedforge/batching.py';s=p.read_text();a=s.index('    first = samples[0]\n',s.index('def _collate'));b=s.index('    return WindowBatch(',a)
s=s[:a]+'''    first = samples[0]
    first_observation, first_action = first["observation"], first["action"]
    for sample in samples:
        observation, action = sample["observation"], sample["action"]
        if observation.keys() != first_observation.keys():
            raise ValueError("Cannot batch different observation schemas")
        if action.shape != first_action.shape or action.dtype != first_action.dtype:
            raise ValueError("Cannot batch different shapes/dtypes for action")
        for key, value in observation.items():
            reference = first_observation[key]
            if value.shape != reference.shape or value.dtype != reference.dtype:
                raise ValueError(f"Cannot batch different shapes/dtypes for obs/{key}")
        if not isinstance(sample["instruction"], str):
            raise ValueError("Batch instructions must be strings")
'''+s[b:]
experimental=r/'experimental-collate';shutil.copytree(r/'reviewed',experimental,ignore=shutil.ignore_patterns('__pycache__'))
(experimental/'src/embodiedforge/batching.py').write_text(s)
module={"__name__":"embodiedforge._experimental_collate","__package__":"embodiedforge"};exec(compile(s,str(experimental/'src/embodiedforge/batching.py'),'exec'),module);after=module['_collate']
os.sched_setaffinity(0,{31});rows=[]
for fields in (1,5,17):
 for size in (1,32,256):
  samples=[dict(observation={f'key{k}':np.full((4,8),i+k,np.float32) for k in range(fields)},action=np.full((8,2),i,np.float32),instruction='collect') for i in range(size)]
  a,b=before(samples),after(samples);assert a.instruction==b.instruction
  for k in a.observation:np.testing.assert_array_equal(a.observation[k],b.observation[k])
  np.testing.assert_array_equal(a.action,b.action)
  count=max(50,20000//size)
  for pair in range(30):
   result={}
   for name,fn in ([('before',before),('after',after)] if pair%2==0 else [('after',after),('before',before)]):
    begin=time.perf_counter()
    for _ in range(count):fn(samples)
    result[name]=(time.perf_counter()-begin)/count
   rows.append(dict(fields=fields,batch_size=size,pair=pair,seconds=result))
  print('completed',fields,size,flush=True)
summary=[]
for fields in (1,5,17):
 for size in (1,32,256):
  group=[x for x in rows if x['fields']==fields and x['batch_size']==size]
  med={name:statistics.median(x['seconds'][name] for x in group) for name in ['before','after']};summary.append(dict(fields=fields,batch_size=size,median_seconds=med,speedup=med['before']/med['after']))
(r/'collate-probe.json').write_text(json.dumps(dict(status='passed',baseline_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),experimental_sha256=hashlib.sha256(s.encode()).hexdigest(),scope='Private collate helper only; same-process alternated timing, CPU31 shared/pinned; output equality. Does not establish complete reader/training throughput.',summary=summary,rows=rows),indent=2)+'\n');print(json.dumps(summary,indent=2))

