"""Warm same-process wall/CPU follow-up for an unchanged ordered-path outlier."""
import hashlib,importlib,importlib.util,json,os,statistics,sys,time
from pathlib import Path
r=Path(__file__).absolute().parent;os.sched_setaffinity(0,{31});started=time.time()
def package(name,folder):
 path=r/folder/'src/embodiedforge';spec=importlib.util.spec_from_file_location(name,path/'__init__.py',submodule_search_locations=[str(path)]);module=importlib.util.module_from_spec(spec);sys.modules[name]=module;spec.loader.exec_module(module);return importlib.import_module(name+'.batching')
modules={'before':package('ef_round7_before','reviewed'),'after':package('ef_round7_after','final')}
rows=[];summaries=[]
configs=[(0,32,4,8,0),(0,256,1,1,0),(12,32,4,8,0),(12,256,1,1,0),(0,32,4,8,128),(12,32,4,8,128)]
for extra,size,history,horizon,shuffle in configs:
 def batches(module):return module.window_batches(r/f'collate-data-extra{extra}',history,horizon,batching=module.BatchOptions(batch_size=size,shuffle_buffer=shuffle))
 fingerprints={}
 for name,module in modules.items():
  h=hashlib.sha256()
  for batch in batches(module):
   for key,value in sorted({'action':batch.action,**batch.observation}.items()):h.update(key.encode());h.update(value.tobytes())
   h.update(json.dumps(batch.instruction).encode())
  fingerprints[name]=h.hexdigest()
 assert len(set(fingerprints.values()))==1
 for _ in range(3):
  for module in modules.values():sum(len(batch.action) for batch in batches(module))
 for pair in range(20):
  times={}
  for name in (list(modules) if pair%2==0 else list(reversed(modules))):
   w=time.perf_counter();c=time.process_time();count=0
   for _ in range(3):count+=sum(len(batch.action) for batch in batches(modules[name]))
   times[name]=dict(wall=(time.perf_counter()-w)/3,cpu=(time.process_time()-c)/3,samples=count//3)
  rows.append(dict(pair=pair,extra_fields=extra,batch_size=size,shuffle_buffer=shuffle,times=times))
 group=[x for x in rows if (x['extra_fields'],x['batch_size'],x['shuffle_buffer'])==(extra,size,shuffle)]
 med={clock:{name:statistics.median(x['times'][name][clock] for x in group) for name in modules} for clock in ['wall','cpu']}
 summaries.append(dict(extra_fields=extra,batch_size=size,history=history,horizon=horizon,shuffle_buffer=shuffle,medians=med,speedup={clock:med[clock]['before']/med[clock]['after'] for clock in med},output_sha256=fingerprints['before']))
 print(json.dumps(summaries[-1]),flush=True)
report=dict(status='passed',started_epoch=started,ended_epoch=time.time(),scope='Same-process complete before/after packages, CPU31 shared/pinned, three warm traversals then 20 alternating pairs of three traversals each. Timed public window_batches/count only; wall and process CPU clocks. No hashing/tracing in timed region. Independent-process ordered 12-extra/B32 control had +10.58% wall-time outlier; all original measurements retained.',summary=summaries,rows=rows)
(r/'ordered-control-confirm.json').write_text(json.dumps(report,indent=2)+'\n')

