"""Randomized exact dataset identities, retry atomicity and window ownership."""
import argparse,gc,hashlib,json,os,signal,sys,tempfile,threading,time
from pathlib import Path
import numpy as np
import embodiedforge
from embodiedforge import Config,VectorEnv
from embodiedforge.data import EpisodeRecorder,read_episodes,EpisodeReadOptions
from embodiedforge.batching import BatchOptions,window_batches
from embodiedforge.tasks import HoldTask
class TimeoutTask(HoldTask):
 def evaluate(self,state,actions,previous):
  reward,_,_=super().evaluate(state,actions,previous)
  done=np.zeros(len(reward),dtype=bool)
  return reward,done,done.copy()
r=Path(__file__).absolute().parent
p=argparse.ArgumentParser();p.add_argument('--until',type=float,required=True);p.add_argument('--label',required=True);a=p.parse_args()
def interrupted(signum,frame):raise SystemExit(128+signum)
signal.signal(signal.SIGTERM,interrupted)
start=time.time();groups=transitions=windows=rejections=0;coverage=set();samples=[]
package=Path(embodiedforge.__file__).parent
source={str(x.relative_to(package)):hashlib.sha256(x.read_bytes()).hexdigest() for x in package.rglob('*.py')}
def resources():return dict(fd=len(list(Path('/proc/self/fd').iterdir())),threads=threading.active_count(),rss_bytes=int(next(x.split()[1] for x in Path('/proc/self/status').read_text().splitlines() if x.startswith('VmRSS:')))*1024)
initial=resources()
def digest_arrays(arrays):
 h=hashlib.sha256()
 for name,value in sorted(arrays.items()):h.update(name.encode());h.update(value.tobytes())
 return h.hexdigest()
def array(values,dtype,layout):
 v=np.asarray(values,dtype=dtype)
 if layout=='strided':
  out=np.empty(len(v)*2,dtype=dtype);out[::2]=v;return out[::2]
 if layout=='reverse':return v[::-1].copy()[::-1]
 if layout=='readonly':v.setflags(write=False)
 return v
try:
 with tempfile.TemporaryDirectory(prefix='ef-round7-identity-') as tmp:
  temp=Path(tmp)
  while time.time()<a.until:
   g=groups;n=(1,3)[g%2];steps=(2,3,7)[(g//2)%3];fmt=('compact','transitions')[(g//6)%2];workers=(0,1,2)[(g//12)%3]
   kind=('i8','u8')[(g//36)%2];order=('<','>')[(g//72)%2];layout=('C','strided','reverse','readonly')[(g//144)%4]
   bounds=[0,1,2**53-1,2**53,2**53+1,2**63-3]
   if kind=='u8':bounds += [2**63,2**64-3]
   base=bounds[(g//576)%len(bounds)];ids=[base+i for i in range(n)];dtype=order+kind
   coverage.add((n,steps,fmt,workers,dtype,layout,base))
   root=temp/'dataset';expected={};invalid_this=0
   with VectorEnv(Config(task='hold',num_envs=n,max_steps=steps,seed=7000000+g),task=TimeoutTask()) as env:
    with EpisodeRecorder(root,env,episode_format=fmt,write_workers=workers) as writer:
     obs=env.observe();obs['episode_id']=array(ids,dtype,layout)
     for step in range(steps):
      result=env.step(np.zeros((n,2),dtype=np.float32));result.observation['episode_id']=array(ids,dtype,layout)
      if step==0:
       original=result.observation['episode_id'];damaged=original.copy();damaged[-1]=int(damaged[-1])+(-1 if int(damaged[-1])==np.iinfo(damaged.dtype).max else 1)
       result.observation['episode_id']=damaged
       before=digest_arrays(obs);retained=writer.buffered_bytes
       try:writer.append(obs,result)
       except ValueError as e:assert 'advance exactly one step' in str(e)
       else:raise AssertionError('Adjacent integer identity accepted')
       assert writer.buffered_bytes==retained and not writer.pending and not list(root.glob('*.npz'))
       assert digest_arrays(obs)==before
       result.observation['episode_id']=original;invalid_this+=1
      for row in range(n):
       item={f'obs/{k}':v[row].copy() for k,v in obs.items()}
       item.update({f'next/{k}':v[row].copy() for k,v in result.observation.items()})
       item.update(action=result.info['executed_action'][row].copy(),reward=result.reward[row].copy(),terminated=result.terminated[row].copy(),truncated=result.truncated[row].copy())
       expected.setdefault(row,[]).append(item)
      before=digest_arrays(obs);next_before=digest_arrays(result.observation)
      writer.append(obs,result)
      assert digest_arrays(obs)==before and digest_arrays(result.observation)==next_before
      obs=result.observation
   decoded=list(read_episodes(root));assert len(decoded)==n
   for ep in decoded:
    row=int(ep['obs/env_id'][0]);want={k:np.stack([x[k] for x in expected[row]]) for k in expected[row][0]}
    assert ep.keys()==want.keys()
    for k in want:np.testing.assert_array_equal(ep[k],want[k])
   projected=list(read_episodes(root,options=EpisodeReadOptions(observation_keys=())))
   required={'env_id','episode_id','step_id','time','proprio'}
   for small,full in zip(projected,decoded):
